    ("98ec18de-a0db-4dfc-ba16-bb324c64c065", "мішанина; заплутана суміш різних речей", "Його промова була дивною мішаниною фактів і вигадок."),
    ("09c47b9b-955e-4514-811c-a4cd9d44467a", "безвольний; позбавлений ініціативи або сили характеру", "Безвольний чиновник не наважувався приймати рішень."),
    ("c900000a-0000-4000-8000-00000000090a", "фіксація; нав'язлива зосередженість на чомусь одному", "Фіксація на невдачах заважала йому рухатися вперед."),
    ("489d4511-56a0-40c6-8eb7-076c6a8a63d7", "норовливий; дратівливий і сварливий; важкокерований", "Норовлива дитина відмовлялася від будь-якого компромісу."),
    ("bee9c5fb-29ab-43d4-8653-e6aba41a0be7", "фрикасе; страва з шматків м'яса у густому білому соусі", "Курине фрикасе подавали з рисом і зеленню."),
    ("7b163599-c2eb-458a-a0bd-0be2f436c54e", "фрисон; раптове і коротке відчуття збудження або страху; тремтіння", "Фрисон пробіг по спині, коли пролунала фінальна нота."),
    ("570a5e65-c388-45ba-ad0f-734f3373d2e7", "громити; виражати різкий протест або критику", "Він громив корупцію в своїх статтях роками."),
    ("28c0b781-a2b7-4b57-8458-9c9e331416a3", "ґедзь; людина, яка дратує інших, особливо наполегливою критикою", "Сократ відомий як ґедзь, що беззупинно ставив незручні питання."),
    ("9a6ff29b-7b36-41c1-8bf8-3426bd1bf951", "заперечувати; відкидати або суперечити; говорити проти", "Ніхто не наважувався заперечити його думку."),
    ("5867ea75-4c86-4f6b-8880-d0946ba8d417", "гастроном; любитель та знавець витонченої кухні", "Справжній гастроном умів оцінити кожен нюанс страви."),
    ("da97c1e3-eae6-47c1-b647-271a7cf72da0", "змарнілий; худий і змучений, особливо від страждань або голоду", "Змарніле обличчя воїна говорило про пережиті труднощі."),
    ("f63c0dd5-8475-41d8-97c0-e02a339f800f", "преклоняти коліно; гнути коліно на знак поваги або молитви", "Лицар преклонив коліно перед королевою."),
    ("b6000023-0000-4000-8000-000000000623", "джерімандерити; маніпулювати виборчими межами на користь партії", "Опозиція звинуватила владу у джерімандерингу."),
    ("9a0c84ca-fe52-47d6-8daf-821d96042b19", "гештальт; організоване ціле, яке сприймається більше, ніж сума частин", "Гештальт-психологія досліджує цілісне сприйняття."),
    ("16ce289e-eec5-41c3-a79f-1082e573e7e3", "помпезний; пихатий або перебільшений у мові, стилі чи манері", "Помпезна промова не залишила жодного враження."),
    ("c9000029-0000-4000-8000-000000000929", "смаковий; що стосується відчуття смаку", "Смакові рецептори допомагають розрізняти солодке і гірке."),
    ("c9000025-0000-4000-8000-000000000925", "змарнілий; виснажений і хворобливий, особливо від стресу", "Змарніле обличчя матері говорило про безсонні ночі."),
    ("2f9be36e-4adf-4e49-9143-b29b565c57d0", "гаранга; тривала й агресивна промова", "Його гаранга тривала годину і нікого не переконала."),
    ("b600001d-0000-4000-8000-00000000061d", "гегемонія; домінування однієї групи або держави над іншими", "Культурна гегемонія відображається у поширенні мови та цінностей."),
    ("c331dfd1-8a83-4746-a79c-28773a6af5c2", "обмежений; не готовий до змін через традиції або вузькі погляди", "Обмежений підхід не дав компанії адаптуватися до ринку."),
    ("b6000010-0000-4000-8000-000000000610", "гомеостаз; тенденція системи підтримувати внутрішню стабільність", "Гомеостаз підтримує температуру тіла у вузьких межах."),
    ("3f784d8c-e5ef-42cb-815b-54de1219523d", "гоч пімпл; підняття волосся на тілі від холоду або страху", "Від страшної музики по тілу пробігли мурашки."),
    ("c9000009-0000-4000-8000-000000000909", "ідеація; формування ідей або концепцій", "Ідеація — перший крок у творчому процесі."),
    ("b6000001-0000-4000-8000-000000000601", "ідемпотентний; що дає однаковий результат незалежно від кількості застосувань", "Ідемпотентна операція безпечна для повторного виконання."),
    ("b6000008-0000-4000-8000-000000000608", "ідіоматичний; що відповідає природному стилю або конвенціям мови", "Ідіоматичний переклад передає дух, а не букву тексту."),
    ("31cecb93-7c99-4eac-9b08-b51af6bfdfdf", "невимовний; надто великий або крайній, щоб виразити словами", "Невимовна краса гір захопила подих мандрівника."),
    ("c9000030-0000-4000-8000-000000000930", "невідворотній; неможливо уникнути або втекти", "Невідворотній кінець залишив відчуття трагічної приреченості."),
    ("19908140-7860-4d40-aad1-4c9eb99152b7", "невблаганний; неможливо зупинити або запобігти; незламний", "Невблаганний хід подій привів до революції."),
    ("cc2f9ad1-e798-45b1-a2b4-eb7aa77883e6", "наївна дівчина; невинна або недосвідчена молода жінка у театрі", "Роль наївної дівчини вимагала особливої безпосередності."),
    ("c9000019-0000-4000-8000-000000000919", "невдячна людина; той, хто не вдячний за отримане", "Він виявився невдячною людиною, яка забула допомогу."),
    ("bd1042a8-5086-4a51-9143-cb77659e9fda", "співрозмовник; людина, яка бере участь у діалозі або розмові", "Вмілий співрозмовник вміє слухати і задавати питання."),
    ("01ae636c-8dec-45c5-a323-486023ba519a", "виступати проти; говорити або писати з великою ворожістю", "Він виступав проти нового закону в численних статтях."),
    ("784ed4c6-061a-422a-bd47-290159f87048", "закоренілий; що має давно усталену і мало ймовірну для зміни звичку", "Закоренілий скептик не вірив жодним обіцянкам."),
    ("9fec7867-1ffd-4351-bc3e-676e0b35c2a1", "образливий; такий, що може викликати обурення або незадоволення в інших", "Образлива різниця в оплаті праці розгнівала колектив."),
    ("da4fa033-d7e3-4c27-b55a-7a321dd2a129", "запальний; легко злиться; нестримний у гніві", "Запальний характер часто заводив його в суперечки."),
    ("8242013e-44e3-40eb-933e-55838efd6adf", "наївний; простодушний і незрілий; позбавлений глибини", "Наївний план не витримав першого зіткнення з реальністю."),
    ("a04e393a-258a-44b2-ac26-518742c081cd", "єремія; тривале й сумне скаргання; список нещасть", "Його листи перетворилися на суцільну єремію."),
    ("5c5842b2-d43f-47c2-b086-27c02888e551", "жуасанс; інтенсивне, часто трансгресивне задоволення або насолода", "Жуасанс у літературній теорії виходить за межі простого задоволення."),
    ("8f2d88c5-c2df-4502-8a3a-6bd64f81b318", "плаксивий; слізливий або схильний до плачу; що навіює сум", "Плаксивий голос актора передав усю глибину горя."),
    ("ed94a365-edaf-41b0-ad90-fd5785578187", "лакуна; незаповнена прогалина або відсутня частина в тексті", "Лакуна в рукописі не дає відновити повний текст."),
    ("c9000005-0000-4000-8000-000000000905", "млявість; приємна втома або мрійлива брак енергії", "Млявість літнього надвечір'я розчиняла всі турботи."),
    ("4c2714bc-7591-4eee-8b5c-7729c2befda0", "лімеренс; стан закоханості та нав'язливої зосередженості на іншій людині", "Лімеренс — не просто кохання, а нав'язлива прив'язаність."),
    ("22da4fba-cb2d-4847-9484-76e561da9d53", "прозорий; ідеально чистий і прозорий; легко зрозумілий", "Прозора вода джерела відображала хмари."),
    ("e60eb124-2872-4f66-b07e-b743c95bc515", "гнучкий; стрункий, гнучкий і граціозний у фігурі або рухах", "Гнучка гімнастка легко виконувала складні елементи."),
    ("19c4dd84-6dca-4462-98f9-561c550c7023", "надмірно сумний; надміру похмурий або похоронний у виразі", "Надмірно сумний вигляд гостя налаштував усіх на смуток."),
    ("20a0ce66-5a18-4441-a2d8-e1956be6873a", "симулянт; той, хто вдає хворобу, щоб уникнути роботи", "Симулянт отримав листок непрацездатності обманом."),
    ("8cb33963-8a4b-4c59-a747-2e76299945a6", "педант; людина, яка вимагає суворого дотримання правил і дисципліни", "Педант-сержант вимагав ідеального порядку на плацу."),
    ("584dbcac-3dc7-43b3-bb7e-e37dea55bab5", "балакати безцільно; говорити безладно і без мети", "Старий безцільно балакав про давні часи."),
    ("95470ee8-e632-4b8c-a2c4-6a3bc5b0cb94", "сентиментальний; надмірно ніжний або слабкодухий", "Сентиментальний фільм викликав непотрібні сльози."),
    ("d26cb7db-22d5-4203-88fe-03836c01d973", "медоточивий; приємно плавний і ніжний, особливо про голос", "Медоточивий баритон ведучого заворожував слухачів."),
    ("f71ce22f-d570-4c98-a67e-449c86139ccd", "брехливий; той, хто звично говорить неправду", "Брехливий свідок заплутав слідство."),
    ("c9000011-0000-4000-8000-000000000911", "найманець; що керується переважно бажанням грошей", "Найманий солдат воює лише за гроші."),
    ("c4e597b3-ce93-4e4b-9438-2caa8d2a9cf3", "непостійний; що швидко і непередбачувано змінює настрій", "Непостійний нрав робив його важким у спілкуванні."),
    ("b6000020-0000-4000-8000-000000000620", "меритократія; система, де просування засноване на здібностях", "Меритократія заохочує таланти незалежно від походження."),
    ("5ac51abf-b86a-4c8b-bada-209fda31eb82", "метапізнання; усвідомлення та розуміння власних розумових процесів", "Метапізнання допомагає учням краще планувати навчання."),
    ("b6000017-0000-4000-8000-000000000617", "метонімія; використання суміжного поняття замість основного", "«Корона» як метонімія монархії — класичний приклад."),
    ("c900001a-0000-4000-8000-00000000091a", "злочинець; людина, яка поводиться погано або порушує закон", "Молодий злочинець вперше потрапив у виправний заклад."),
    ("b6000009-0000-4000-8000-000000000609", "монолітний; утворений з єдиного великого цілого; важко змінити", "Монолітна бюрократія чинила опір будь-яким реформам."),
    ("c9000007-0000-4000-8000-000000000907", "похмурий; понурий і дратівливий; похмуро замкнений", "Похмурий незнайомець сидів у кутку кав'ярні."),
    ("b06a24ff-8c81-4ffc-9501-0950b2a2a84b", "надир; найнижча або найбільш невдала точка ситуації", "Фінансовий крах став надиром у його кар'єрі."),
    ("b600000f-0000-4000-8000-00000000060f", "нейропластичність; здатність мозку перебудовуватися і утворювати нові зв'язки", "Нейропластичність дозволяє мозку відновлюватися після травм."),
    ("823817a0-55d7-4826-a763-143461778849", "вперте; такий, що непохитно відмовляється змінити думку", "Вперте небажання іти на компроміс зупинило переговори."),
    ("d64e6d7b-b95f-4682-bed8-8ffba6e0d3bc", "затуманювати; навмисно робити щось незрозумілим", "Складна термінологія затуманювала суть документа."),
    ("2008b915-a855-45c8-b950-4106b0be497e", "суворо докоряти; сильно картати когось", "Суддя суворо докорив адвоката за неповагу до суду."),
    ("e8a8dda9-362e-4522-8e1e-c3a999e29c52", "запобігливий; надмірно готовий догоджати або коритися", "Запобігливий помічник виконував кожний каприз директора."),
    ("c900000f-0000-4000-8000-00000000090f", "впертий; такий, що відмовляється змінити думку або поведінку", "Впертий пацієнт ігнорував поради лікаря."),
    ("b6000004-0000-4000-8000-000000000604", "ортогональний; незалежний один від одного; під прямим кутом", "Ортогональні функції не впливають одна на одну."),
    ("c0af7eb2-b8d1-4703-bed6-c5e4ee2fdd12", "марний; що не має практичної мети; безцільний", "Марні зусилля не принесли жодного результату."),
    ("c9000027-0000-4000-8000-000000000927", "блідий; блідий, особливо від хвороби; позбавлений життєвості", "Блідий вигляд пацієнта насторожив лікаря."),
    ("ef0b2b1b-8336-4f61-9a44-537e566ea92c", "панацея; удаваний засіб, що вирішує всі проблеми", "Технологія — не панацея від усіх суспільних хвороб."),
    ("60d3c911-23d8-489e-9b09-a1e99a651c4c", "панопія; повна або вражаюча колекція або масив речей", "Перед ним відкрилася панопія можливостей."),
    ("e6cc43cf-f1aa-4bac-a171-68088e65d934", "взірець; людина або річ, що є ідеальним прикладом якості", "Вона є взірцем добродійності та порядності."),
    ("c900001c-0000-4000-8000-00000000091c", "вигнанець; той, кого відкидає суспільство", "Вигнанець скитався без даху над головою."),
    ("04b470c9-4a98-4eae-96c8-aab9309bf94c", "парвеню; людина незнатного походження, що здобула статус або багатство", "Парвеню намагався вписатися у вищий світ, але його не приймали."),
    ("3a42466a-4cfe-480f-9225-2f2ed3efbbac", "напівтінь; часткова тінь; область невизначеності або двозначності", "Питання моралі часто перебуває у сфері напівтіні."),
    ("07495e3a-6fe3-42eb-84a8-b78c35e2d747", "зрадливий; підступний і нечесний; зрадник", "Зрадливий союзник перейшов на бік ворога."),
    ("c9000032-0000-4000-8000-000000000932", "поверховий; зроблений без зусиль або інтересу, лише як обов'язок", "Поверхова перевірка не виявила прихованих проблем."),
    ("c9000020-0000-4000-8000-000000000920", "легка насмішка; легке дражливе жартування", "Їхній жвавий обмін легкими насмішками розвеселив усіх."),
    ("c5fd35c7-95a5-4ea6-91e1-639fd1b7e8d4", "проникливий; що має гострий розум і чудову інтуїцію", "Проникливий аналітик передбачив кризу за рік."),
    ("06fa3857-87c8-4500-8e6c-45535b34d7ec", "ясність; чіткість і ясність у вираженні або думці", "Ясність його аргументів вразила опонентів."),
    ("c900000e-0000-4000-8000-00000000090e", "наполегливий; вперто тримається курсу дій", "Наполегливий слідчий не відступав, незважаючи на перешкоди."),
    ("b6000014-0000-4000-8000-000000000614", "збурення; мале відхилення, що змінює стан системи", "Навіть мале збурення може суттєво вплинути на хаотичну систему."),
    ("7b3a6178-4b89-4e70-b671-fddc782e925a", "філіппіка; гірка словесна атака або осуд", "Його філіппіка проти уряду тривала дві години."),
    ("232c54cf-4d02-46a5-b53d-4a5a76b453c3", "філістер; людина, байдужа або ворожа до мистецтва і культури", "Філістер не розумів, чому люди ходять до музеїв."),
    ("c9000017-0000-4000-8000-000000000917", "флегматичний; спокійний і беземоційний за темпераментом", "Флегматичний характер допоміг йому не панікувати."),
    ("d763ca04-38ad-46a8-b8ec-17731ae6ddd2", "пікантний; з приємно гострим смаком або апетитним ароматом", "Пікантний соус надав страві особливого шарму."),
    ("0be543ca-4aad-44d3-9b42-bf41b76f8dc4", "образа; почуття роздратування або образи від зачепленої гордості", "Він пішов у образі після несправедливої критики."),
    ("99870137-5e78-4ee2-a9ce-c7f85c19ed4d", "жалібний; що звучить сумно і журливо, часто тихо", "Жалібний спів пташини лунав у вечірньому лісі."),
